import React, { useEffect, useState } from 'react';
import { askAIQuestion, setApiKey } from '../../services/aiService';
import { addFlashCardToSet, getFlashCardSets, FlashCardSet } from '../../services/flashCardService';
import MarkdownRenderer from '../MarkdownRenderer/index';
import {
  PageContainer,
  Title,
  Form,
  Label,
  Input,
  Select,
  TextArea,
  Button,
  Output,
  Info,
  Row,
  ErrorMsg,
  Success
} from './AIChatPage.styles';

const AIChatPage: React.FC = () => {
  const [question, setQuestion] = useState('');
  const [topic, setTopic] = useState('');
  const [answer, setAnswer] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [sets, setSets] = useState<FlashCardSet[]>([]);
  const [targetSetId, setTargetSetId] = useState<string>('default');
  const [geminiApiKey, setGeminiApiKey] = useState('');
  const [hasEnvGeminiKey, setHasEnvGeminiKey] = useState(false);
  const [includeCode, setIncludeCode] = useState(false);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    // load sets
    setSets(getFlashCardSets());
    // API key bootstrap
    if (process.env.REACT_APP_GEMINI_API_KEY) {
      setHasEnvGeminiKey(true);
      setApiKey(process.env.REACT_APP_GEMINI_API_KEY);
    } else {
      const savedKey = localStorage.getItem('gemini_api_key');
      if (savedKey) {
        setGeminiApiKey(savedKey);
        setApiKey(savedKey);
      }
    }
  }, []);

  useEffect(() => {
    if (!hasEnvGeminiKey && geminiApiKey) {
      localStorage.setItem('gemini_api_key', geminiApiKey);
      setApiKey(geminiApiKey);
    }
  }, [geminiApiKey, hasEnvGeminiKey]);

  const onAsk = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaved(false);
    if (!question.trim()) {
      setError('Please enter a question');
      return;
    }
    if (!hasEnvGeminiKey && !geminiApiKey.trim()) {
      setError('Please provide a Google Gemini API key');
      return;
    }
    setError('');
    setIsLoading(true);
    try {
      const resp = await askAIQuestion({ question, topic: topic || undefined, tone: 'detailed', includeCode });
      setAnswer(resp);
    } catch (err: any) {
      setError(err?.message || 'Failed to get AI answer');
    } finally {
      setIsLoading(false);
    }
  };

  const onSave = () => {
    if (!answer.trim()) {
      setError('No AI answer to save');
      return;
    }
    const topicToUse = topic || 'General';
    const updated = addFlashCardToSet(targetSetId, { topic: topicToUse, question, answer });
    if (!updated) {
      setError('Failed to save flash card');
      return;
    }
    setSaved(true);
  };

  return (
    <PageContainer>
      <Title>Flash Card Chat Assistant</Title>
      <Info>
        Ask a question and let the AI generate an answer. You can then add the answer as a flash card to a set.
      </Info>
      <Form onSubmit={onAsk}>
        {!hasEnvGeminiKey && (
          <div>
            <Label htmlFor="key">Google Gemini API Key</Label>
            <Input id="key" type="password" value={geminiApiKey} onChange={(e) => setGeminiApiKey(e.target.value)} placeholder="Enter your API key" />
          </div>
        )}
        <Row>
          <div>
            <Label htmlFor="topic">Topic (optional)</Label>
            <Input id="topic" value={topic} onChange={(e) => setTopic(e.target.value)} placeholder="e.g., React Hooks" />
          </div>
          <div>
            <Label htmlFor="set">Save to Set</Label>
            <Select id="set" value={targetSetId} onChange={(e) => setTargetSetId(e.target.value)}>
              {sets.map(s => (
                <option key={s.id} value={s.id}>{s.name}</option>
              ))}
            </Select>
          </div>
        </Row>
        <div>
          <Label htmlFor="question">Your Question</Label>
          <TextArea id="question" value={question} onChange={(e) => setQuestion(e.target.value)} placeholder="Type your question here..." />
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <input 
            id="includeCode" 
            type="checkbox" 
            checked={includeCode} 
            onChange={(e) => setIncludeCode(e.target.checked)} 
          />
          <Label htmlFor="includeCode" style={{ marginBottom: 0, fontWeight: 400 }}>Include Code Examples</Label>
        </div>
        {error && <ErrorMsg>{error}</ErrorMsg>}
        <div style={{ display: 'flex', gap: 8 }}>
          <Button type="submit" disabled={isLoading}>{isLoading ? 'Asking…' : 'Ask Flash Card'}</Button>
          <Button type="button" onClick={onSave} disabled={!answer || isLoading}>Add as Flash Card</Button>
        </div>
      </Form>

      {answer && (
        <div style={{ marginTop: 16 }}>
          <Label>AI Answer</Label>
          <Output>
            <MarkdownRenderer content={answer} />
          </Output>
          {saved && <Success>Saved to set!</Success>}
        </div>
      )}
    </PageContainer>
  );
};

export default AIChatPage;
