import React, { useState } from 'react';
import { FlashCard as FlashCardType } from '../../types';
import FlashCard, { CardWidth } from '../FlashCard/index';
import { clearSetNotes } from '../../services/api';
import { exportCardsToPdf } from '../../services/pdfService';
import {
  DeckContainer,
  ControlsContainer,
  WidthControls,
  ActionButtons,
  ActionButton,
  WidthButton,
  NavigationButtons,
  NavButton,
  DangerButton,
  CardCounter
} from './FlashCardDeck.styles';

interface FlashCardDeckProps {
  cards: FlashCardType[];
}

const FlashCardDeck: React.FC<FlashCardDeckProps> = ({ cards }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [widthSetting, setWidthSetting] = useState<CardWidth>('standard');
  
  const goToNextCard = () => {
    if (currentIndex < cards.length - 1) {
      setCurrentIndex(currentIndex + 1);
    }
  };
  
  const goToPreviousCard = () => {
    if (currentIndex > 0) {
      setCurrentIndex(currentIndex - 1);
    }
  };

  const handleClearAllNotes = async () => {
    if (cards.length === 0) return;
    const firstCard = cards[0] as any;
    const setId = firstCard.set_id;

    if (!setId) {
      alert('Could not identify the card set to clear notes.');
      return;
    }

    if (window.confirm('Are you sure you want to remove ALL interview notes from this deck?')) {
      try {
        await clearSetNotes(setId);
        cards.forEach(c => c.note = undefined);
        alert('All notes cleared.');
      } catch (err) {
        alert('Failed to clear notes.');
      }
    }
  };
  
  if (!cards || cards.length === 0) {
    return <DeckContainer>No flash cards available.</DeckContainer>;
  }
  
  const safeIndex = Math.min(currentIndex, cards.length - 1);
  
  const handleExportPdf = () => {
    exportCardsToPdf(cards, 'Interview Flash Cards Deck');
  };

  return (
    <DeckContainer widthSetting={widthSetting}>
      <ControlsContainer>
        <WidthControls>
          <span style={{ fontSize: '14px', alignSelf: 'center', marginRight: '5px', fontWeight: 600, color: '#666' }}>Card Width:</span>
          <WidthButton 
            active={widthSetting === 'standard'} 
            onClick={() => setWidthSetting('standard')}
          >
            Standard
          </WidthButton>
          <WidthButton 
            active={widthSetting === 'wide'} 
            onClick={() => setWidthSetting('wide')}
          >
            Wide
          </WidthButton>
          <WidthButton 
            active={widthSetting === 'full'} 
            onClick={() => setWidthSetting('full')}
          >
            Page Width
          </WidthButton>
        </WidthControls>

        <ActionButtons>
          <ActionButton onClick={handleExportPdf}>
            Export Deck to PDF
          </ActionButton>
        </ActionButtons>
      </ControlsContainer>

      <FlashCard card={cards[safeIndex]} widthSetting={widthSetting} />
      <CardCounter>
        Card {safeIndex + 1} of {cards.length}
      </CardCounter>
      <NavigationButtons style={{ maxWidth: widthSetting === 'standard' ? '600px' : widthSetting === 'wide' ? '1000px' : '100%' }}>
        <NavButton 
          onClick={goToPreviousCard} 
          disabled={safeIndex === 0}
        >
          Previous
        </NavButton>
        <NavButton 
          onClick={goToNextCard} 
          disabled={safeIndex === cards.length - 1}
        >
          Next
        </NavButton>
      </NavigationButtons>

      {cards.some(c => c.note) && (
        <DangerButton onClick={handleClearAllNotes}>
          Remove All Notes from this Deck
        </DangerButton>
      )}
    </DeckContainer>
  );
};

export default FlashCardDeck;
