import React from 'react';
import AIFlashCardGenerator from '../AIFlashCardGenerator/index';
import { FlashCard } from '../../types';
import { addFlashCardSet } from '../../services/flashCardService';
import { saveFlashCardSet } from '../../services/api';
import { PageContainer, Title } from './AIGeneratorPage.styles';

interface AIGeneratorPageProps {
  onFlashCardsGenerated: () => void;
}

const AIGeneratorPage: React.FC<AIGeneratorPageProps> = ({ onFlashCardsGenerated }) => {
  const handleFlashCardsGenerated = async (flashCards: FlashCard[], setName: string) => {
    // Add the generated flash cards as a new set in localStorage
    addFlashCardSet(setName, flashCards);
    
    // Also save to server if logged in
    try {
      await saveFlashCardSet(setName, flashCards);
    } catch (e) {
      console.error('Failed to save flash cards to server:', e);
    }
    
    // Notify the parent component that new flash cards have been generated
    onFlashCardsGenerated();
  };
  
  return (
    <PageContainer>
      <Title>Flash Card Generator</Title>
      <AIFlashCardGenerator onFlashCardsGenerated={handleFlashCardsGenerated} />
    </PageContainer>
  );
};

export default AIGeneratorPage;
