import React from 'react';
import { FlashCard } from '../../types';
import { useNavigate } from 'react-router-dom';
import {
  PageContainer,
  Title,
  TopicsGrid,
  TopicCard,
  TopicName,
  CardCount
} from './TopicsPage.styles';

interface TopicsPageProps {
  cards: FlashCard[];
}

const TopicsPage: React.FC<TopicsPageProps> = ({ cards }) => {
  const navigate = useNavigate();
  
  // Get unique topics and count cards for each
  const topicCounts = cards.reduce((acc, card) => {
    acc[card.topic] = (acc[card.topic] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  // Sort topics alphabetically
  const topics = Object.keys(topicCounts).sort();
  
  const handleTopicClick = (topic: string) => {
    // Navigate to the flash card deck with the selected topic
    navigate('/', { state: { selectedTopic: topic } });
  };

  return (
    <PageContainer>
      <Title>Select a Topic</Title>
      
      <TopicsGrid>
        <TopicCard onClick={() => handleTopicClick('')}>
          <TopicName>All Topics</TopicName>
          <CardCount>{cards.length} cards</CardCount>
        </TopicCard>
        
        {topics.map(topic => (
          <TopicCard key={topic} onClick={() => handleTopicClick(topic)}>
            <TopicName>{topic}</TopicName>
            <CardCount>{topicCounts[topic]} cards</CardCount>
          </TopicCard>
        ))}
      </TopicsGrid>
    </PageContainer>
  );
};

export default TopicsPage;
