import React, { useState, useEffect } from 'react';
import { FlashCard } from '../../types';
import { 
  generateFlashCards, 
  setApiKey, 
} from '../../services/aiService';
import {
  FormContainer,
  Title,
  Form,
  FormGroup,
  Label,
  Input,
  TextArea,
  Select,
  Button,
  ErrorMessage,
  LoadingContainer,
  LoadingSpinner,
  LoadingText,
  SuccessMessage,
  InfoBox
} from './AIFlashCardGenerator.styles';

interface AIFlashCardGeneratorProps {
  onFlashCardsGenerated: (flashCards: FlashCard[], setName: string) => void;
}

const AIFlashCardGenerator: React.FC<AIFlashCardGeneratorProps> = ({ onFlashCardsGenerated }) => {
  const [topics, setTopics] = useState('');
  const [skillLevel, setSkillLevel] = useState('Beginner');
  const [questionsPerTopic, setQuestionsPerTopic] = useState(5);
  const [setName, setSetName] = useState('');
  const [conversationStyle, setConversationStyle] = useState(false);
  const [includeCode, setIncludeCode] = useState(false);
  const [jobDescription, setJobDescription] = useState('');
  const [isReadingFile, setIsReadingFile] = useState(false);
  const [geminiApiKey, setGeminiApiKey] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);
  
  // Check if API key is available from environment variable
  const [hasEnvGeminiKey, setHasEnvGeminiKey] = useState(false);
  
  useEffect(() => {
    // Check if we have API key from environment variable
    console.log('Gemini Environment API key:', process.env.REACT_APP_GEMINI_API_KEY ? 'Available' : 'Not available');
    
    // Check for Gemini API key
    if (process.env.REACT_APP_GEMINI_API_KEY) {
      console.log('Setting hasEnvGeminiKey to true');
      setHasEnvGeminiKey(true);
      // Explicitly set the API key in the service
      setApiKey(process.env.REACT_APP_GEMINI_API_KEY);
    } else {
      console.log('No Gemini environment API key found');
      // If no environment API key, try to load from localStorage
      const savedGeminiKey = localStorage.getItem('gemini_api_key');
      if (savedGeminiKey) {
        setGeminiApiKey(savedGeminiKey);
        // Set it in the service
        setApiKey(savedGeminiKey);
      }
    }
  }, []);
  
  // Update the Gemini API key in the service when it changes
  useEffect(() => {
    if (!hasEnvGeminiKey && geminiApiKey) {
      console.log('Saving Gemini API key to localStorage and setting in service');
      // Save to localStorage for persistence
      localStorage.setItem('gemini_api_key', geminiApiKey);
      // Set in the service
      setApiKey(geminiApiKey);
    } else if (hasEnvGeminiKey && process.env.REACT_APP_GEMINI_API_KEY) {
      console.log('Setting Gemini environment API key in service');
      // Ensure the environment API key is set in the service
      setApiKey(process.env.REACT_APP_GEMINI_API_KEY);
    }
  }, [geminiApiKey, hasEnvGeminiKey]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    console.log('Form submitted - hasEnvGeminiKey:', hasEnvGeminiKey);
    console.log('Form submitted - Gemini API key provided:', geminiApiKey ? 'Yes' : 'No');
    
    // Validation: topics required only if no job description provided
    const hasJD = Boolean(jobDescription && jobDescription.trim());
    if (!hasJD && !topics.trim()) {
      setError('Please enter at least one topic (or provide a job description).');
      return;
    }
    
    if (!setName.trim()) {
      setError('Please enter a name for this flash card set');
      return;
    }
    
    // Check if we have the required API key
    if (!hasEnvGeminiKey && !geminiApiKey.trim()) {
      setError('Please enter your Google Gemini API key');
      return;
    }
    
    setError('');
    setIsLoading(true);
    setSuccess(false);
    
    try {
      // Set the API key in the service
      if (!hasEnvGeminiKey) {
        console.log('Setting user-provided Gemini API key');
        setApiKey(geminiApiKey);
      } else {
        console.log('Using Gemini environment API key');
        setApiKey(process.env.REACT_APP_GEMINI_API_KEY || '');
      }
      
      let topicsList = topics.split(',').map(topic => topic.trim()).filter(topic => topic.length > 0);

      // If no topics entered but JD provided, use a sensible placeholder topic
      if (topicsList.length === 0 && hasJD) {
        topicsList = ['Based on Job Description'];
      }
      if (topicsList.length === 0) {
        throw new Error('No valid topics found. Please enter at least one topic or include a job description.');
      }
      
      console.log('Generating flash cards for topics:', topicsList);
      
      // Call the AI service to generate flash cards
      const generatedCards = await generateFlashCards({
        topics: topicsList,
        skillLevel: skillLevel as 'Beginner' | 'Novice' | 'Advanced',
        questionsPerTopic,
        conversationStyle,
        jobDescription: jobDescription || undefined,
        includeCode
      });
      
      if (generatedCards.length === 0) {
        throw new Error('No flash cards were generated. Please try again with different topics.');
      }
      
      // Check if we got placeholder content
      const allPlaceholders = generatedCards.every(card => 
        card.answer.includes('involves understanding key principles and applying them effectively')
      );
      
      if (allPlaceholders) {
        console.error('All generated cards are placeholders');
        throw new Error(
          'Could not generate AI content. The model may have returned non-specific content or there was a temporary service issue. Please verify your API key/quota and try again.'
        );
      }
      
      onFlashCardsGenerated(generatedCards, setName);
      setSuccess(true);
    } catch (err) {
      console.error('Error in handleSubmit:', err);
      
      if (err instanceof Error) {
        // Format specific error messages for better user experience
        if (err.message.includes('API key')) {
          setError(`API Key Error: ${err.message} Please verify your Google Gemini API key, quota, and model availability.`);
        } else if (err.message.includes('rate limit') || err.message.includes('quota')) {
          setError(`Rate Limit Error: Google Gemini API rate limit exceeded. Please wait a few minutes and try again.`);
        } else if (err.message.includes('timeout') || err.message.includes('network')) {
          setError(`Network Error: Failed to connect to Google Gemini. Please check your internet connection and try again.`);
        } else {
          setError(`Error: ${err.message}`);
        }
      } else {
        setError(`Failed to generate flash cards with Google Gemini. Please try again later.`);
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <FormContainer>
      <Title>Generate Flash Cards</Title>
      <InfoBox>
        <strong>How it works:</strong> This tool uses Google Gemini Pro AI to generate custom flash cards based on your topics.
        {!hasEnvGeminiKey && " You'll need to provide your own Gemini API key."} The generated cards will be saved as a new flash card set.
        <br /><br />
        <strong>Tips for best results:</strong>
        <ul style={{ marginTop: '5px', paddingLeft: '20px' }}>
          <li>Be specific with your topics (e.g., "React Hooks" instead of just "React")</li>
          <li>For technical topics, choose the appropriate skill level</li>
          <li>Start with 3-5 questions per topic to test the results</li>
          {!hasEnvGeminiKey && <li>Your API key is stored only in your browser's local storage</li>}
          <li>Each topic will generate unique questions based on the skill level</li>
        </ul>
      </InfoBox>
      
      <Form onSubmit={handleSubmit}>
        <FormGroup>
          <Label htmlFor="setName">Flash Card Set Name</Label>
          <Input
            id="setName"
            type="text"
            value={setName}
            onChange={(e) => setSetName(e.target.value)}
            placeholder="Enter a unique name for this set"
            required
          />
        </FormGroup>

        {/* Job description input (optional) */}
        <FormGroup>
          <Label htmlFor="jobDescription">Job description (optional)</Label>
          <TextArea
            id="jobDescription"
            value={jobDescription}
            onChange={(e) => setJobDescription(e.target.value)}
            placeholder="Paste a job description here to tailor questions to the role (responsibilities, required skills, tools, scenarios)."
          />
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginTop: 8 }}>
            <input
              id="jobDescriptionFile"
              type="file"
              accept=".txt,.md,.rtf,.csv,.json,text/*,application/json"
              onChange={(e) => {
                const file = e.target.files && e.target.files[0];
                if (!file) return;
                const MAX_SIZE = 1024 * 1024; // 1MB
                if (file.size > MAX_SIZE) {
                  setError('File too large. Please upload a file up to 1 MB.');
                  return;
                }
                setError('');
                setIsReadingFile(true);
                const reader = new FileReader();
                reader.onload = () => {
                  try {
                    let text = String(reader.result || '');
                    // If JSON, try to pretty-print short strings
                    if (file.type === 'application/json' || file.name.endsWith('.json')) {
                      try {
                        const parsed = JSON.parse(text);
                        text = typeof parsed === 'string' ? parsed : JSON.stringify(parsed, null, 2);
                      } catch {}
                    }
                    setJobDescription(text);
                  } finally {
                    setIsReadingFile(false);
                  }
                };
                reader.onerror = () => {
                  setIsReadingFile(false);
                  setError('Failed to read the selected file.');
                };
                reader.readAsText(file);
              }}
            />
          </div>
          <div style={{ fontSize: '12px', marginTop: '5px', color: '#666' }}>
            You can paste text or upload a text-based file (TXT, MD, RTF, CSV, JSON). The content will guide the AI.
          </div>
        </FormGroup>

        <FormGroup>
          <Label htmlFor="conversationStyle">
            <input
              id="conversationStyle"
              type="checkbox"
              checked={conversationStyle}
              onChange={(e) => setConversationStyle(e.target.checked)}
              style={{ marginRight: 8 }}
            />
            Conversation style Q/A (Interviewer ↔ Candidate)
          </Label>
          <div style={{ fontSize: '12px', marginTop: '5px', color: '#666' }}>
            If checked, the AI will return answers as a short dialogue between an Interviewer and a Candidate.
          </div>
        </FormGroup>

        <FormGroup>
          <Label htmlFor="includeCode">
            <input
              id="includeCode"
              type="checkbox"
              checked={includeCode}
              onChange={(e) => setIncludeCode(e.target.checked)}
              style={{ marginRight: 8 }}
            />
            Include Code Examples
          </Label>
          <div style={{ fontSize: '12px', marginTop: '5px', color: '#666' }}>
            If checked, the AI will include illustrative code examples where relevant.
          </div>
        </FormGroup>
        
        {/* Gemini API Key input */}
        {!hasEnvGeminiKey && (
          <FormGroup>
            <Label htmlFor="geminiApiKey">Google Gemini API Key</Label>
            <Input
              id="geminiApiKey"
              type="password"
              value={geminiApiKey}
              onChange={(e) => setGeminiApiKey(e.target.value)}
              placeholder="Enter your Google Gemini API key"
            />
            <div style={{ fontSize: '12px', marginTop: '5px', color: '#666' }}>
              Your API key is stored locally in your browser and is never sent to our servers.
              <br />
              You can get an API key from <a href="https://ai.google.dev/" target="_blank" rel="noopener noreferrer">Google AI Studio</a>.
            </div>
          </FormGroup>
        )}
        
        {/* Show a message if environment API key is available */}
        {hasEnvGeminiKey && (
          <div style={{ padding: '10px', backgroundColor: '#e8f5e9', borderRadius: '4px', marginBottom: '15px' }}>
            <span style={{ color: '#2e7d32' }}>✓</span> Using Google Gemini API key from environment configuration
          </div>
        )}
        
        <FormGroup>
          <Label htmlFor="topics">Topics</Label>
          <TextArea
            id="topics"
            value={topics}
            onChange={(e) => setTopics(e.target.value)}
            placeholder="Enter topics separated by commas (e.g., JavaScript, React, Node.js)"
            required={!jobDescription.trim()}
          />
          <div style={{ fontSize: '12px', marginTop: '5px', color: '#666' }}>
            {jobDescription.trim()
              ? 'Topics are optional when a job description is provided.'
              : 'Topics are required unless you provide a job description.'}
          </div>
        </FormGroup>
        
        <FormGroup>
          <Label htmlFor="skillLevel">Skill Level</Label>
          <Select
            id="skillLevel"
            value={skillLevel}
            onChange={(e) => setSkillLevel(e.target.value)}
          >
            <option value="Beginner">Beginner</option>
            <option value="Novice">Novice</option>
            <option value="Advanced">Advanced</option>
          </Select>
        </FormGroup>
        
        <FormGroup>
          <Label htmlFor="questionsPerTopic">Questions Per Topic</Label>
          <Input
            id="questionsPerTopic"
            type="number"
            min="1"
            max="20"
            value={questionsPerTopic}
            onChange={(e) => setQuestionsPerTopic(parseInt(e.target.value))}
          />
        </FormGroup>
        
        {error && <ErrorMessage>{error}</ErrorMessage>}
        
        <Button type="submit" disabled={isLoading || isReadingFile}>
          {isLoading ? 'Generating...' : 'Generate Flash Cards'}
        </Button>
      </Form>
      
      {isLoading && (
        <LoadingContainer>
          <LoadingSpinner />
          <LoadingText>
            Generating flash cards...
            <br />
            This may take a minute or two depending on the number of topics.
          </LoadingText>
        </LoadingContainer>
      )}
      
      {success && (
        <SuccessMessage>
          <strong>Success!</strong> Flash cards generated and saved as a new set.
          <br />
          You can now select this set from the dropdown menu at the top of the page.
        </SuccessMessage>
      )}
    </FormContainer>
  );
};

export default AIFlashCardGenerator;
