import { FlashCard } from '../types';

const API_BASE = process.env.REACT_APP_API_BASE || 'http://localhost:3001';

function getAuthHeader(): Record<string, string> {
  const token = localStorage.getItem('token');
  return token ? { 'Authorization': `Bearer ${token}` } : {};
}

export async function login(username: string, password: string): Promise<any> {
  const resp = await fetch(`${API_BASE}/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ username, password })
  });
  if (!resp.ok) {
    const err = await resp.json();
    throw new Error(err.error || 'Login failed');
  }
  const data = await resp.json();
  localStorage.setItem('token', data.token);
  localStorage.setItem('user', JSON.stringify({ username: data.username, userId: data.userId }));
  return data;
}

export async function register(username: string, password: string): Promise<any> {
  const resp = await fetch(`${API_BASE}/register`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ username, password })
  });
  if (!resp.ok) {
    const err = await resp.json();
    throw new Error(err.error || 'Registration failed');
  }
  const data = await resp.json();
  localStorage.setItem('token', data.token);
  localStorage.setItem('user', JSON.stringify({ username: data.username, userId: data.userId }));
  return data;
}

export function logout() {
  localStorage.removeItem('token');
  localStorage.removeItem('user');
}

export function getCurrentUser() {
  const user = localStorage.getItem('user');
  return user ? JSON.parse(user) : null;
}

export async function fetchDefaultFlashCards(): Promise<FlashCard[]> {
  const url = `${API_BASE}/flashcards`;
  const resp = await fetch(url, {
    headers: getAuthHeader()
  });
  if (!resp.ok) {
    throw new Error(`Failed to fetch flashcards: ${resp.status} ${resp.statusText}`);
  }
  const data = await resp.json();
  const cards = (data && (data.flashcards || data.cards || data.data)) as any[];
  if (!Array.isArray(cards)) {
    throw new Error('Invalid flashcards response format');
  }
  // Ensure typing
  return cards.map((c, idx) => ({
    id: typeof c.id === 'number' ? c.id : idx + 1,
    topic: c.topic,
    question: c.question || c.front,
    answer: c.answer || c.back,
    note: c.note,
    set_id: c.set_id,
  } as FlashCard));
}

export async function saveFlashCardSet(setName: string, cards: FlashCard[]): Promise<any> {
  const url = `${API_BASE}/flashcards`;
  
  // We save cards one by one or we could add a bulk endpoint. 
  // For now, let's use the POST /flashcards endpoint which handles set creation too.
  
  const results = [];
  for (const card of cards) {
    const resp = await fetch(url, {
      method: 'POST',
      headers: { 
        'Content-Type': 'application/json',
        ...getAuthHeader()
      },
      body: JSON.stringify({
        topic: card.topic,
        question: card.question,
        answer: card.answer,
        setName
      })
    });
    if (resp.ok) {
      results.push(await resp.json());
    }
  }
  return results;
}

