// Generate flashcards from the server for a single topic using the AI endpoint
export async function generateFlashCardsForTopic(topic: string): Promise<FlashCard[]> {
  const url = `${API_BASE}/generate-flashcards`;
  const resp = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ topic })
  });
  if (!resp.ok) {
    let errMsg = `Failed to generate flashcards: ${resp.status} ${resp.statusText}`;
    try {
      const errJson = await resp.json();
      if (errJson && errJson.error) errMsg = `${errMsg} - ${errJson.error}`;
    } catch {}
    throw new Error(errMsg);
  }
  const data = await resp.json();
  const raw = (data && (data.flashcards || data.cards || data.data)) as any[];
  if (!Array.isArray(raw)) {
    throw new Error('Invalid response format from AI flashcard generation');
  }
  return raw.map((c, idx) => ({
    id: idx + 1, // temporary; will be reassigned when saved
    topic,
    question: c.question || c.front,
    answer: c.answer || c.back,
  } as FlashCard));
}

export async function fetchDbTables(): Promise<string[]> {
  try {
    const resp = await fetch(`${API_BASE}/db/tables`);
    if (!resp.ok) {
      const err = await resp.json().catch(() => ({}));
      throw new Error(err.error || `Failed to fetch tables: ${resp.status}`);
    }
    const data = await resp.json();
    return data.tables || [];
  } catch (e: any) {
    if (e.message.includes('Failed to fetch')) {
      throw new Error('Could not connect to the server. Make sure it is running on ' + API_BASE);
    }
    throw e;
  }
}

export async function fetchTableData(table: string): Promise<any[]> {
  const resp = await fetch(`${API_BASE}/db/data/${table}`);
  if (!resp.ok) throw new Error(`Failed to fetch data for ${table}`);
  const data = await resp.json();
  return data.data;
}

export async function executeRawQuery(query: string): Promise<any[]> {
  const resp = await fetch(`${API_BASE}/db/query`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ query })
  });
  if (!resp.ok) {
    const err = await resp.json();
    throw new Error(err.error || 'Query failed');
  }
  const data = await resp.json();
  return data.result;
}

