import React from 'react';
import { FlashCard } from '../../types';
import {
  TopicContainer,
  TopicTitle,
  TopicButtonsContainer,
  TopicButton,
  CardCount
} from './TopicSelector.styles';

interface TopicSelectorProps {
  cards: FlashCard[];
  selectedTopic: string | null;
  onSelectTopic: (topic: string | null) => void;
}

const TopicSelector: React.FC<TopicSelectorProps> = ({ 
  cards, 
  selectedTopic, 
  onSelectTopic 
}) => {
  // Get unique topics and count cards for each
  const topicCounts = cards.reduce((acc, card) => {
    acc[card.topic] = (acc[card.topic] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  // Sort topics alphabetically
  const topics = Object.keys(topicCounts).sort();

  return (
    <TopicContainer>
      <TopicTitle>Filter by Topic</TopicTitle>
      <TopicButtonsContainer>
        <TopicButton 
          isSelected={selectedTopic === null}
          onClick={() => onSelectTopic(null)}
        >
          All Topics
          <CardCount color={selectedTopic === null ? 'rgba(255, 255, 255, 0.2)' : undefined}>
            {cards.length}
          </CardCount>
        </TopicButton>
        
        {topics.map(topic => (
          <TopicButton 
            key={topic}
            isSelected={selectedTopic === topic}
            onClick={() => onSelectTopic(topic)}
          >
            {topic}
            <CardCount color={selectedTopic === topic ? 'rgba(255, 255, 255, 0.2)' : undefined}>
              {topicCounts[topic]}
            </CardCount>
          </TopicButton>
        ))}
      </TopicButtonsContainer>
    </TopicContainer>
  );
};

export default TopicSelector;
