import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Link, NavLink as RouterNavLink, useParams, useLocation } from 'react-router-dom';
import styled from 'styled-components';
import FlashCardDeck from './components/FlashCardDeck/index';
import FlashCardList from './components/FlashCardList/index';
import TopicSelector from './components/TopicSelector/index';
import TopicsPage from './components/TopicsPage/index';
import FlashCardSetSelector from './components/FlashCardSetSelector/index';
import AIGeneratorPage from './components/AIGeneratorPage/index';
import AIChatPage from './components/AIChatPage/index';
import AuthModal from './components/AuthModal/index';
import DatabaseViewer from './components/DatabaseViewer/index';
import { getFlashCardSetById, getFlashCardSets } from './services/flashCardService';
import { fetchDefaultFlashCards, generateFlashCardsForTopic, getCurrentUser, logout } from './services/api';
import { saveJsonFile, DEFAULT_FILENAME } from './services/fileSystemService';
import { flashCards as bundledFlashCards } from './data/flashCards';

const AppContainer = styled.div`
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  background-color: #f5f7fa;
  min-height: 100vh;
`;

const Header = styled.header`
  background-color: #4a90e2;
  color: white;
  padding: 20px;
  text-align: center;
`;

const Title = styled.h1`
  margin: 0;
  font-size: 28px;
`;

const Navigation = styled.nav`
  display: flex;
  justify-content: center;
  background-color: #357abD;
  padding: 10px;
`;

const NavLink = styled(RouterNavLink)`
  color: white;
  text-decoration: none;
  padding: 8px 16px;
  margin: 0 10px;
  border-radius: 4px;
  transition: background-color 0.3s;
  
  &:hover {
    background-color: rgba(255, 255, 255, 0.1);
  }
  
  &.active {
    background-color: rgba(255, 255, 255, 0.2);
    font-weight: bold;
  }
`;

const UserSection = styled.div`
  display: flex;
  align-items: center;
  color: white;
  margin-left: auto;
  padding: 0 20px;
`;

const UserButton = styled.button`
  background-color: rgba(255, 255, 255, 0.2);
  color: white;
  border: none;
  padding: 5px 15px;
  border-radius: 4px;
  cursor: pointer;
  margin-left: 10px;
  
  &:hover {
    background-color: rgba(255, 255, 255, 0.3);
  }
`;

const AppContent: React.FC = () => {
  const [selectedTopic, setSelectedTopic] = useState<string | null>(null);
  const [selectedSetId, setSelectedSetId] = useState<string>('default');
  const [currentCards, setCurrentCards] = useState<any[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [user, setUser] = useState<any>(getCurrentUser());
  const [showAuthModal, setShowAuthModal] = useState(false);
  const location = useLocation();
  
  // On first mount, ensure default set is available by fetching from server if needed
  useEffect(() => {
    const ensureDefault = async () => {
      try {
        let cards = await fetchDefaultFlashCards();
        // If server returned an empty array, fall back to bundled cards
        if (!Array.isArray(cards) || cards.length === 0) {
          cards = bundledFlashCards;
        }

        const defaultSet = {
          id: 'default',
          name: 'Default Flash Cards',
          filename: DEFAULT_FILENAME,
          cards,
        };
        saveJsonFile(DEFAULT_FILENAME, defaultSet);
        setSelectedSetId('default');
        setCurrentCards(cards);
      } catch (e) {
        console.error('Failed to fetch default flashcards from server:', e);
        // Fallback to local sets if server fails
        const sets = getFlashCardSets();
        if (sets.length > 0) {
          setSelectedSetId(sets[0].id);
          setCurrentCards(sets[0].cards);
        } else if (bundledFlashCards && bundledFlashCards.length > 0) {
          const defaultSet = {
            id: 'default',
            name: 'Default Flash Cards',
            filename: DEFAULT_FILENAME,
            cards: bundledFlashCards,
          };
          saveJsonFile(DEFAULT_FILENAME, defaultSet);
          setSelectedSetId('default');
          setCurrentCards(bundledFlashCards);
        }
      }
    };
    // fire and forget
    void ensureDefault();
  }, [user]);

  const handleLoginSuccess = (userData: any) => {
    setUser(userData);
    setShowAuthModal(false);
  };

  const handleLogout = () => {
    logout();
    setUser(null);
  };

  // Load the selected flash card set
  useEffect(() => {
    const set = getFlashCardSetById(selectedSetId);
    if (set) {
      setCurrentCards(set.cards);
    } else {
      // If set not found, load the first available set
      const sets = getFlashCardSets();
      if (sets.length > 0) {
        setSelectedSetId(sets[0].id);
        setCurrentCards(sets[0].cards);
      }
    }
  }, [selectedSetId]);
  
  // Check if a topic was selected from the TopicsPage
  useEffect(() => {
    if (location.state && location.state.selectedTopic !== undefined) {
      // If empty string was passed, set to null (all topics)
      const topicFromNavigation = location.state.selectedTopic === '' 
        ? null 
        : location.state.selectedTopic;
      
      setSelectedTopic(topicFromNavigation);
      
      // Clear the location state to avoid reapplying on refresh
      window.history.replaceState({}, document.title);
    }
  }, [location]);
  
  // Filter cards based on selected topic
  const filteredCards = selectedTopic 
    ? currentCards.filter((card: any) => card.topic === selectedTopic)
    : currentCards;
  
  // Handle when new flash cards are generated
  const handleFlashCardsGenerated = () => {
    // Refresh the current cards from the selected set
    const set = getFlashCardSetById(selectedSetId);
    if (set) {
      setCurrentCards(set.cards);
    }
  };

  // Generate AI cards for the currently selected topic and append to current set
  const handleGenerateForTopic = async () => {
    if (!selectedTopic) {
      alert('Please select a topic first.');
      return;
    }
    setIsGenerating(true);
    try {
      const newCards = await generateFlashCardsForTopic(selectedTopic);
      if (!newCards || newCards.length === 0) {
        alert('The AI did not return any cards.');
        return;
      }
      // Append to current set persistently
      const set = getFlashCardSetById(selectedSetId);
      if (!set) {
        alert('No flash card set selected.');
        return;
      }
      // Use service to add one by one so IDs are reassigned sequentially
      for (const c of newCards) {
        const { addFlashCardToSet } = await import('./services/flashCardService');
        addFlashCardToSet(set.id, { topic: c.topic, question: c.question, answer: c.answer });
      }
      // Refresh
      handleFlashCardsGenerated();
    } catch (e: any) {
      console.error('Failed to generate AI cards for topic:', e);
      alert(e?.message || 'Failed to generate AI cards. Check the server and API key.');
    } finally {
      setIsGenerating(false);
    }
  };
    
  return (
    <AppContainer>
      <Header>
        <Title>Interview Flash Cards</Title>
      </Header>
      <Navigation>
        <NavLink to="/" end>Flash Card Deck</NavLink>
        <NavLink to="/list">All Cards</NavLink>
        <NavLink to="/topics">Topics</NavLink>
        <NavLink to="/generator">Flash Card Generator</NavLink>
        <NavLink to="/chat">Flash Card Chat</NavLink>
        <NavLink to="/db">Database</NavLink>
        
        <UserSection>
          {user ? (
            <>
              <span>Welcome, {user.username}</span>
              <UserButton onClick={handleLogout}>Logout</UserButton>
            </>
          ) : (
            <UserButton onClick={() => setShowAuthModal(true)}>Login / Register</UserButton>
          )}
        </UserSection>
      </Navigation>

      {showAuthModal && (
        <AuthModal 
          onClose={() => setShowAuthModal(false)} 
          onLoginSuccess={handleLoginSuccess} 
        />
      )}
      
      <FlashCardSetSelector 
        key={`${selectedSetId}-${currentCards.length}`}
        selectedSetId={selectedSetId}
        onSelectSet={setSelectedSetId}
      />
      
      <Routes>
        <Route path="/" element={
          <>
            <TopicSelector 
              cards={currentCards} 
              selectedTopic={selectedTopic} 
              onSelectTopic={setSelectedTopic} 
            />
            <div style={{ display: 'flex', justifyContent: 'center', gap: 12, margin: '10px 0 20px' }}>
              <button 
                onClick={handleGenerateForTopic} 
                disabled={!selectedTopic || isGenerating}
                style={{ padding: '8px 12px', background: '#4a90e2', color: '#fff', border: 'none', borderRadius: 4, cursor: (!selectedTopic || isGenerating) ? 'not-allowed' : 'pointer' }}
              >
                {isGenerating ? 'Generating…' : `Generate Flash Cards${selectedTopic ? ` for "${selectedTopic}"` : ''}`}
              </button>
              {!selectedTopic && (
                <span style={{ color: '#666', fontSize: 12 }}>Select a topic to enable generation</span>
              )}
            </div>
            <FlashCardDeck cards={filteredCards} />
          </>
        } />
        <Route path="/list" element={
          <>
            <TopicSelector 
              cards={currentCards} 
              selectedTopic={selectedTopic} 
              onSelectTopic={setSelectedTopic} 
            />
            <FlashCardList cards={filteredCards} />
          </>
        } />
        <Route path="/cards/:id" element={<SingleCardView />} />
        <Route path="/topics" element={<TopicsPage cards={currentCards} />} />
        <Route path="/generator" element={<AIGeneratorPage onFlashCardsGenerated={handleFlashCardsGenerated} />} />
        <Route path="/chat" element={<AIChatPage />} />
        <Route path="/db" element={<DatabaseViewer />} />
      </Routes>
    </AppContainer>
  );
};

const App: React.FC = () => {
  return (
    <Router>
      <AppContent />
    </Router>
  );
};

// Component to display a single card when clicked from the list
const SingleCardView: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const cardId = parseInt(id || '0', 10);
  
  // Get all sets and search for the card in each set
  const allSets = getFlashCardSets();
  let foundCard = null;
  
  // Search for the card in all sets
  for (const set of allSets) {
    const card = set.cards.find(card => card.id === cardId);
    if (card) {
      foundCard = card;
      break;
    }
  }
  
  if (!foundCard) {
    return (
      <div style={{ textAlign: 'center', padding: '50px' }}>
        <h2>Card not found</h2>
        <Link to="/list">Back to list</Link>
      </div>
    );
  }
  
  return (
    <div style={{ padding: '20px' }}>
      <FlashCardDeck cards={[foundCard]} />
      <div style={{ textAlign: 'center', marginTop: '20px' }}>
        <Link to="/list" style={{ color: '#4a90e2' }}>Back to list</Link>
      </div>
    </div>
  );
};

export default App;
