import React, { useState } from 'react';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { vscDarkPlus } from 'react-syntax-highlighter/dist/esm/styles/prism';
import {
  Container,
  Header,
  Language,
  ToggleButton,
  CodeWrapper
} from './MarkdownRenderer.styles';

interface MarkdownRendererProps {
  content: string;
}

const MarkdownRenderer: React.FC<MarkdownRendererProps> = ({ content }) => {
  // Use an object to track visibility of multiple code blocks by their index
  const [visibleBlocks, setVisibleBlocks] = useState<Record<number, boolean>>({});

  const toggleVisibility = (index: number) => {
    setVisibleBlocks(prev => ({
      ...prev,
      [index]: !prev[index]
    }));
  };

  // A simple markdown-like parser for code blocks
  const parts = content.split(/(```[\s\S]*?```)/g);

  return (
    <div>
      {parts.map((part, index) => {
        if (part.startsWith('```')) {
          const match = part.match(/```(\w+)?\n?([\s\S]*?)```/);
          if (match) {
            const language = match[1] || 'javascript';
            const code = match[2].trim();
            const isVisible = visibleBlocks[index] ?? true; // Default to visible

            return (
              <Container key={index}>
                <Header>
                  <Language>{language}</Language>
                  <ToggleButton onClick={() => toggleVisibility(index)}>
                    {isVisible ? 'Hide Code' : 'Show Code'}
                  </ToggleButton>
                </Header>
                <CodeWrapper isVisible={isVisible}>
                  <SyntaxHighlighter
                    language={language}
                    style={vscDarkPlus}
                    customStyle={{ margin: 0 }}
                  >
                    {code}
                  </SyntaxHighlighter>
                </CodeWrapper>
              </Container>
            );
          }
        }
        
        return (
          <span key={index} style={{ whiteSpace: 'pre-wrap' }}>
            {part}
          </span>
        );
      })}
    </div>
  );
};

export default MarkdownRenderer;
