import React, { useState, useEffect } from 'react';
import { FlashCardSet, getFlashCardSets, deleteFlashCardSet, flashCardEvents } from '../../services/flashCardService';
import {
  SelectorContainer,
  Title,
  SelectWrapper,
  Select,
  Button,
  SetInfo
} from './FlashCardSetSelector.styles';

interface FlashCardSetSelectorProps {
  selectedSetId: string;
  onSelectSet: (setId: string) => void;
}

const FlashCardSetSelector: React.FC<FlashCardSetSelectorProps> = ({ 
  selectedSetId, 
  onSelectSet 
}) => {
  const [flashCardSets, setFlashCardSets] = useState<FlashCardSet[]>([]);
  const [selectedSet, setSelectedSet] = useState<FlashCardSet | undefined>();
  
  // Load flash card sets
  useEffect(() => {
    const sets = getFlashCardSets();
    setFlashCardSets(sets);
    
    // If no set is selected, select the default one
    if (!selectedSetId && sets.length > 0) {
      onSelectSet(sets[0].id);
    }
    
    // Find the selected set
    const selected = sets.find(set => set.id === selectedSetId);
    setSelectedSet(selected);
  }, [selectedSetId, onSelectSet]);

  // Subscribe to global set change events so the selector refreshes without page reload
  useEffect(() => {
    const refresh = () => {
      const sets = getFlashCardSets();
      setFlashCardSets(sets);
      const selected = sets.find(s => s.id === selectedSetId);
      setSelectedSet(selected);
    };

    // Some environments may not support EventTarget in SSR; guard addEventListener
    const anyEvents: any = flashCardEvents as any;
    if (anyEvents && typeof anyEvents.addEventListener === 'function') {
      anyEvents.addEventListener('setsChanged', refresh);
      anyEvents.addEventListener('setUpdated', refresh);
    }

    return () => {
      if (anyEvents && typeof anyEvents.removeEventListener === 'function') {
        anyEvents.removeEventListener('setsChanged', refresh);
        anyEvents.removeEventListener('setUpdated', refresh);
      }
    };
  }, [selectedSetId]);
  
  // Handle set selection change
  const handleSetChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const setId = e.target.value;
    onSelectSet(setId);
  };
  
  // Handle set deletion
  const handleDeleteSet = () => {
    if (!selectedSetId || selectedSetId === 'default') return;
    
    if (window.confirm('Are you sure you want to delete this flash card set?')) {
      const success = deleteFlashCardSet(selectedSetId);
      
      if (success) {
        // Refresh the list of sets
        const updatedSets = getFlashCardSets();
        setFlashCardSets(updatedSets);
        
        // Select the default set
        if (updatedSets.length > 0) {
          onSelectSet(updatedSets[0].id);
        }
      }
    }
  };
  
  return (
    <SelectorContainer>
      <Title>Flash Card Set</Title>
      <SelectWrapper>
        <Select value={selectedSetId} onChange={handleSetChange}>
          {flashCardSets.map(set => (
            <option key={set.id} value={set.id}>
              {set.name}
            </option>
          ))}
        </Select>
        <Button 
          onClick={handleDeleteSet} 
          disabled={!selectedSetId || selectedSetId === 'default'}
          title={selectedSetId === 'default' ? 'Cannot delete the default set' : 'Delete this set'}
        >
          Delete
        </Button>
      </SelectWrapper>
      {selectedSet && (
        <SetInfo>
          {selectedSet.cards.length} cards in this set
        </SetInfo>
      )}
    </SelectorContainer>
  );
};

export default FlashCardSetSelector;
