import React, { useState, useEffect } from 'react';
import { FlashCard as FlashCardType } from '../../types';
import MarkdownRenderer from '../MarkdownRenderer/index';
import { updateFlashCardNote, deleteFlashCardNote } from '../../services/api';
import {
  CardContainer,
  QuestionSection,
  AnswerSection,
  Topic,
  Content,
  Question,
  AnswerContainer,
  NoteSection,
  NoteHeader,
  NoteTitle,
  NoteContent,
  NoteActions,
  ActionButton,
  NoteTextArea,
  DialogueContainer,
  TurnRow,
  RoleBadge,
  TurnText,
  Button,
  CardWidth
} from './FlashCard.styles';

export type { CardWidth };

interface FlashCardProps {
  card: FlashCardType;
  widthSetting?: CardWidth;
}

const FlashCard: React.FC<FlashCardProps> = ({ card, widthSetting = 'standard' }) => {
  const [showAnswer, setShowAnswer] = useState(false);
  const [isEditingNote, setIsEditingNote] = useState(false);
  const [noteText, setNoteText] = useState(card?.note || '');

  useEffect(() => {
    setNoteText(card?.note || '');
    setIsEditingNote(false);
  }, [card]);

  const toggleAnswer = () => {
    setShowAnswer(!showAnswer);
  };

  const handleSaveNote = async () => {
    if (!card) return;
    try {
      await updateFlashCardNote(card.id, noteText);
      card.note = noteText; // Update local object
      setIsEditingNote(false);
    } catch (err) {
      alert('Failed to save note');
    }
  };

  const handleDeleteNote = async () => {
    if (!card) return;
    if (window.confirm('Are you sure you want to delete this note?')) {
      try {
        await deleteFlashCardNote(card.id);
        card.note = undefined; // Update local object
        setNoteText('');
        setIsEditingNote(false);
      } catch (err) {
        alert('Failed to delete note');
      }
    }
  };

  // Handle case where card is undefined
  if (!card) {
    return (
      <CardContainer widthSetting={widthSetting}>
        <QuestionSection>
          <Content>
            <Question>Card not available</Question>
          </Content>
        </QuestionSection>
      </CardContainer>
    );
  }

  // Helpers to detect and parse conversation-style answers
  const isConversation = (text: string): boolean => {
    if (!text) return false;
    const lower = text.toLowerCase();
    return lower.includes('interviewer:') || lower.includes('candidate:');
  };

  type Turn = { role: 'Interviewer' | 'Candidate'; text: string };

  const parseConversation = (text: string): Turn[] => {
    if (!text) return [];
    let t = text.trim();
    // Strip enclosing quotes or code fences if present
    if ((t.startsWith('"') && t.endsWith('"')) || (t.startsWith("'") && t.endsWith("'"))) {
      t = t.slice(1, -1);
    }
    t = t.replace(/```(?:json)?\n?|```/g, '').trim();

    const lines = t.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
    const turns: Turn[] = [];
    const re = /^\s*"?(interviewer|candidate)\s*[:\-–]\s*"?/i;
    for (const line of lines) {
      const m = line.match(re);
      if (m) {
        const roleRaw = m[1].toLowerCase();
        const role: Turn['role'] = roleRaw === 'interviewer' ? 'Interviewer' : 'Candidate';
        const textPart = line.replace(re, '').trim().replace(/^"|"$/g, '');
        turns.push({ role, text: textPart });
      }
    }
    return turns;
  };

  const renderAnswer = (answer: string) => {
    if (isConversation(answer)) {
      const turns = parseConversation(answer);
      if (turns.length >= 2) {
        return (
          <DialogueContainer>
            {turns.map((turn, idx) => (
              <TurnRow key={idx} role={turn.role}>
                <RoleBadge role={turn.role}>{turn.role}</RoleBadge>
                <TurnText>{turn.text}</TurnText>
              </TurnRow>
            ))}
          </DialogueContainer>
        );
      }
      // Fallback to raw if parsing failed
    }
    return <MarkdownRenderer content={answer} />;
  };

  return (
    <CardContainer widthSetting={widthSetting}>
      <QuestionSection>
        <Topic>{card.topic}</Topic>
        <Content>
          <Question>{card.question}</Question>
          <Button onClick={toggleAnswer}>
            {showAnswer ? 'Hide Answer' : 'Show Answer'}
          </Button>
        </Content>
      </QuestionSection>
      <AnswerSection isOpen={showAnswer}>
        <AnswerContainer>
          {renderAnswer(card.answer)}
          
          <NoteSection>
            <NoteHeader>
              <NoteTitle>Interview Notes</NoteTitle>
              {!isEditingNote && (
                <NoteActions>
                  <ActionButton onClick={() => setIsEditingNote(true)}>
                    {card.note ? 'Edit Note' : 'Add Note'}
                  </ActionButton>
                  {card.note && (
                    <ActionButton color="#e74c3c" onClick={handleDeleteNote}>
                      Delete
                    </ActionButton>
                  )}
                </NoteActions>
              )}
            </NoteHeader>

            {isEditingNote ? (
              <div>
                <NoteTextArea 
                  value={noteText} 
                  onChange={(e) => setNoteText(e.target.value)}
                  placeholder="Add your thoughts or extra info for this interview question..."
                />
                <div style={{ display: 'flex', gap: 10 }}>
                  <Button onClick={handleSaveNote} style={{ marginTop: 0, padding: '5px 15px', fontSize: '14px' }}>
                    Save Note
                  </Button>
                  <Button 
                    onClick={() => {
                      setIsEditingNote(false);
                      setNoteText(card.note || '');
                    }} 
                    style={{ marginTop: 0, padding: '5px 15px', fontSize: '14px', backgroundColor: '#999' }}
                  >
                    Cancel
                  </Button>
                </div>
              </div>
            ) : (
              card.note && (
                <NoteContent>
                  <MarkdownRenderer content={card.note} />
                </NoteContent>
              )
            )}
          </NoteSection>
        </AnswerContainer>
      </AnswerSection>
    </CardContainer>
  );
};

export default FlashCard;
