import React, { useState } from 'react';
import { FlashCard as FlashCardType } from '../../types';
import { CardWidth } from '../FlashCard/index';
import { exportCardsToPdf } from '../../services/pdfService';
import {
  ListContainer,
  ControlsContainer,
  WidthControls,
  ActionButtons,
  ActionButton,
  WidthButton,
  Title,
  CardList,
  CardItem,
  CardLink,
  CardQuestion,
  CardTopic,
  BackButton
} from './FlashCardList.styles';

interface FlashCardListProps {
  cards: FlashCardType[];
}

const FlashCardList: React.FC<FlashCardListProps> = ({ cards }) => {
  const [widthSetting, setWidthSetting] = useState<CardWidth>('standard');

  const handleExportPdf = () => {
    exportCardsToPdf(cards, 'All Interview Flash Cards');
  };

  return (
    <ListContainer widthSetting={widthSetting}>
      <Title>All Flash Cards</Title>

      <ControlsContainer>
        <WidthControls>
          <span style={{ fontSize: '14px', alignSelf: 'center', marginRight: '5px', fontWeight: 600, color: '#666' }}>List Width:</span>
          <WidthButton 
            active={widthSetting === 'standard'} 
            onClick={() => setWidthSetting('standard')}
          >
            Standard
          </WidthButton>
          <WidthButton 
            active={widthSetting === 'wide'} 
            onClick={() => setWidthSetting('wide')}
          >
            Wide
          </WidthButton>
          <WidthButton 
            active={widthSetting === 'full'} 
            onClick={() => setWidthSetting('full')}
          >
            Page Width
          </WidthButton>
        </WidthControls>

        <ActionButtons>
          <ActionButton onClick={handleExportPdf}>
            Export List to PDF
          </ActionButton>
        </ActionButtons>
      </ControlsContainer>
      
      {cards.length === 0 ? (
        <p>No flash cards available.</p>
      ) : (
        <CardList>
          {cards.map((card) => (
            <CardItem key={card.id}>
              <CardLink to={`/cards/${card.id}`}>
                <CardQuestion>{card.question}</CardQuestion>
                <CardTopic>{card.topic}</CardTopic>
              </CardLink>
            </CardItem>
          ))}
        </CardList>
      )}
      
      <BackButton to="/">Back to Deck</BackButton>
    </ListContainer>
  );
};

export default FlashCardList;
