import React, { useState, useEffect } from 'react';
import { fetchDbTables, fetchTableData, executeRawQuery } from '../../services/api';
import {
  Container,
  Section,
  Title,
  TableList,
  TableButton,
  QueryEditor,
  TextArea,
  Button,
  TableContainer,
  StyledTable,
  ErrorMessage
} from './DatabaseViewer.styles';

const DatabaseViewer: React.FC = () => {
  const [tables, setTables] = useState<string[]>([]);
  const [activeTable, setActiveTable] = useState<string | null>(null);
  const [tableData, setTableData] = useState<any[]>([]);
  const [query, setQuery] = useState('');
  const [queryResult, setQueryResult] = useState<any[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    loadTables();
  }, []);

  const loadTables = async () => {
    try {
      const names = await fetchDbTables();
      setTables(names);
    } catch (e: any) {
      setError(e.message);
    }
  };

  const handleTableClick = async (table: string) => {
    setLoading(true);
    setActiveTable(table);
    setError(null);
    setQueryResult([]);
    try {
      const data = await fetchTableData(table);
      setTableData(data);
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  const handleRunQuery = async () => {
    if (!query.trim()) return;
    setLoading(true);
    setError(null);
    setActiveTable(null);
    setTableData([]);
    try {
      const result = await executeRawQuery(query);
      setQueryResult(result);
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  const renderData = (data: any[]) => {
    if (data.length === 0) return <p>No data found.</p>;

    const headers = Object.keys(data[0]);

    return (
      <TableContainer>
        <StyledTable>
          <thead>
            <tr>
              {headers.map(h => <th key={h}>{h}</th>)}
            </tr>
          </thead>
          <tbody>
            {data.map((row, i) => (
              <tr key={i}>
                {headers.map(h => <td key={h}>{JSON.stringify(row[h])}</td>)}
              </tr>
            ))}
          </tbody>
        </StyledTable>
      </TableContainer>
    );
  };

  return (
    <Container>
      <Title>Database Explorer</Title>
      
      {error && <Section style={{ border: '1px solid #e74c3c' }}><ErrorMessage>{error}</ErrorMessage></Section>}

      <Section>
        <h3>Tables</h3>
        <TableList>
          {tables.map(t => (
            <TableButton 
              key={t} 
              active={activeTable === t} 
              onClick={() => handleTableClick(t)}
            >
              {t}
            </TableButton>
          ))}
          {tables.length === 0 && <p>Loading tables...</p>}
        </TableList>
      </Section>

      <Section>
        <h3>SQL Query</h3>
        <QueryEditor>
          <TextArea 
            placeholder="SELECT * FROM flashcards WHERE topic = 'React'..." 
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
          <Button onClick={handleRunQuery} disabled={loading}>
            {loading ? 'Running...' : 'Run Query'}
          </Button>
        </QueryEditor>
      </Section>

      {activeTable && (
        <Section>
          <h3>Data: {activeTable}</h3>
          {loading ? <p>Loading data...</p> : renderData(tableData)}
        </Section>
      )}

      {queryResult.length > 0 && (
        <Section>
          <h3>Query Results</h3>
          {renderData(queryResult)}
        </Section>
      )}
    </Container>
  );
};

export default DatabaseViewer;
